class ModuleNodeOnTaskVisitor(object):
    def __init__(self,l):
        self.l = l
        self._levelInTasks = 0
    def enter(self,visitee):
        if isinstance(visitee, Task):
            self._levelInTasks += 1
        if self._levelInTasks == 0:
            return
        if visitee.isLeaf():
            self.l.append(visitee)
        pass
    def leave(self,visitee):
        if self._levelInTasks > 0:
            if isinstance(visitee, Task):
                self._levelInTasks -= 1

