class Module(object):
    def __init__(self):
        self.writeHistFile = False

    def beginJob(self, histFile=None, histDirName=None):
        if histFile != None and histDirName != None:
            self.writeHistFile = True
            prevdir = ROOT.gDirectory
            self.histFile = histFile
            self.histFile.cd()
            self.dir = self.histFile.mkdir(histDirName, "", True)
            prevdir.cd()
            self.objs = []

    def endJob(self):
        if hasattr(self, 'objs') and self.objs != None:
            prevdir = ROOT.gDirectory
            self.dir.cd()
            for obj in self.objs:
                obj.Write()
            prevdir.cd()

    def beginFile(self, inputFile, outputFile, inputTree, wrappedOutputTree):
        pass

    def endFile(self, inputFile, outputFile, inputTree, wrappedOutputTree):
        pass

    def analyze(self, event):
        """process event, return True (go to next module) or False (fail, go to next event)"""
        pass

    def addObject(self, obj):
        setattr(self, obj.GetName(), obj)
        self.objs.append(getattr(self, obj.GetName()))

    def addObjectList(self, names, obj):
        objlist = []
        for iname, name in enumerate(names):
            setattr(self, obj.GetName() + '_' + name,
                    obj.Clone(obj.GetName() + '_' + name))
            objlist.append(getattr(self, obj.GetName() + '_' + name))
            self.objs.append(getattr(self, obj.GetName() + '_' + name))
        setattr(self, obj.GetName(), objlist)

def eventLoop(
        modules, inputFile, outputFile, inputTree, wrappedOutputTree,
        maxEvents=-1, eventRange=None, progress=(10000, sys.stdout),
        filterOutput=True
):
    for m in modules:
        m.beginFile(inputFile, outputFile, inputTree, wrappedOutputTree)

    t0 = time.time()
    tlast = t0
    doneEvents = 0
    acceptedEvents = 0
    entries = inputTree.entries
    if eventRange:
        entries = len(eventRange)
    if maxEvents > 0:
        entries = min(entries, maxEvents)

    for ie, i in enumerate(range(entries) if eventRange == None else eventRange):
        if maxEvents > 0 and ie >= maxEvents:
            break
        e = Event(inputTree, i)
        clearExtraBranches(inputTree)
        doneEvents += 1
        ret = True
        for m in modules:
            ret = m.analyze(e)
            if not ret:
                break
        if ret:
            acceptedEvents += 1
        if (ret or not filterOutput) and wrappedOutputTree != None:
            wrappedOutputTree.fill()
        if progress:
            if ie > 0 and ie % progress[0] == 0:
                t1 = time.time()
                progress[1].write("Processed %8d/%8d entries, %5.2f%% (elapsed time %7.1fs, curr speed %8.3f kHz, avg speed %8.3f kHz), accepted %8d/%8d events (%5.2f%%)\n" % (
                    ie, entries, ie / float(0.01 * entries),
                    t1 - t0, (progress[0] / 1000.) / (max(t1 - tlast, 1e-9)),
                    ie / 1000. / (max(t1 - t0, 1e-9)),
                    acceptedEvents, doneEvents,
                    acceptedEvents / (0.01 * doneEvents)))
                tlast = t1
    for m in modules:
        m.endFile(inputFile, outputFile, inputTree, wrappedOutputTree)
    return (doneEvents, acceptedEvents, time.time() - t0)

from PhysicsTools.NanoAODTools.postprocessing.framework.treeReaderArrayTools import setExtraBranch
from array import array
import ROOT
ROOT.PyConfig.IgnoreCommandLineOptions = True

_rootBranchType2PythonArray = {
    'b': 'B',
    'B': 'b',
    's': 'H',
    'S': 'h',
    'i': 'I',
    'I': 'i',
    'F': 'f',
    'D': 'd',
    'l': 'L',
    'L': 'l',
    'O': 'B'
}

# Convert data type string returned by TLeaf.GetTypeName() to root branch type
_rootDataType2BranchType ={
    'UChar_t'   : 'b',
    'Char_t'    : 'B',
    'UShort_t'  : 's',
    'Short_t'   : 'S',
    'UInt_t'    : 'i',
    'Int_t'     : 'I',
    'Float_t'   : 'F',
    'Double_t'  : 'D',
    'ULong64_t' : 'l',
    'Long64_t'  : 'L',
    'Bool_t'    : 'O'
}

class OutputBranch:
    def __init__(
            self, tree, name, rootBranchType, n=1,
            lenVar=None, title=None, limitedPrecision=False
    ):
        n = int(n)
        self.n = n
        self.lenVar = lenVar
        self.precision = ROOT.MiniFloatConverter.ReduceMantissaToNbitsRounding(
            limitedPrecision) if limitedPrecision and rootBranchType == 'F' else lambda x: x
        # check if a branch was already there
        existingBranch = tree.GetBranch(name)
        if (existingBranch):
            existingBranchType = _rootDataType2BranchType[existingBranch.FindLeaf(name).GetTypeName()]
            if rootBranchType != existingBranchType :
                print(f'Warning: output branch {name} already exists with type {existingBranchType}. Will ignore specified type {rootBranchType}')
            self.buff = array(
                _rootBranchType2PythonArray[existingBranchType], n * [0. if existingBranchType in 'FD' else 0])
            self.branch = existingBranch
            self.branch.SetAddress(self.buff)
        else:
            self.buff = array(
                _rootBranchType2PythonArray[rootBranchType], n * [0. if rootBranchType in 'FD' else 0])
            if lenVar != None:
                self.branch = tree.Branch(
                    name, self.buff, "%s[%s]/%s" % (name, lenVar, rootBranchType))
            elif n == 1:
                self.branch = tree.Branch(
                    name, self.buff, name + "/" + rootBranchType)
            else:
                self.branch = tree.Branch(
                    name, self.buff, "%s[%d]/%s" % (name, n, rootBranchType))
        if title:
            self.branch.SetTitle(title)

    def fill(self, val):
        if self.lenVar:
            if len(self.buff) < len(val):  # realloc
                self.buff = array(self.buff.typecode, max(
                    len(val), 2 * len(self.buff)) * [0. if self.buff.typecode in 'fd' else 0])
                self.branch.SetAddress(self.buff)
            for i, v in enumerate(val):
                self.buff[i] = self.precision(v)
        elif self.n == 1:
            self.buff[0] = self.precision(val)
        else:
            if len(val) != self.n:
                raise RuntimeError("Mismatch in filling branch %s of fixed length %d with %d values (%s)" % (
                    self.branch.GetName(), self.n, len(val), val))
            for i, v in enumerate(val):
                self.buff[i] = v

class OutputTree:
    def __init__(self, tfile, ttree, intree):
        self._file = tfile
        self._tree = ttree
        self._intree = intree
        self._branches = {}

    def branch(
            self, name, rootBranchType, n=1, lenVar=None,
            title=None, limitedPrecision=False
    ):
        # and (not self._tree.GetBranch(lenVar)):
        if (lenVar != None) and (lenVar not in self._branches):
            self._branches[lenVar] = OutputBranch(self._tree, lenVar, "I")
        self._branches[name] = OutputBranch(
            self._tree, name, rootBranchType, n=n,
            lenVar=lenVar, title=title, limitedPrecision=limitedPrecision
        )
        return self._branches[name]

    def fillBranch(self, name, val):
        br = self._branches[name]
        if br.lenVar and (br.lenVar in self._branches):
            self._branches[br.lenVar].buff[0] = len(val)
            setExtraBranch(self._intree, br.lenVar, len(val))
        br.fill(val)
        setExtraBranch(self._intree, name, val)

    def tree(self):
        return self._tree

    def fill(self):
        self._tree.Fill()

    def write(self):
        self._file.cd()
        self._tree.Write()

class FullOutput(OutputTree):
    def __init__(
            self,
            inputFile,
            inputTree,
            outputFile,
            branchSelection=None,
            outputbranchSelection=None,
            fullClone=False,
            maxEntries=None,
            firstEntry=0,
            provenance=False,
            jsonFilter=None
    ):
        outputFile.cd()

        self.outputbranchSelection = outputbranchSelection
        self.maxEntries = maxEntries
        self.firstEntry = firstEntry
        if fullClone:
            outputTree = inputTree.CopyTree(
                '1', "", maxEntries if maxEntries else ROOT.TVirtualTreePlayer.kMaxEntries, firstEntry)
        else:
            outputTree = inputTree.CloneTree(0)
        ROOT.SetOwnership(outputTree, False)

        # enable back all branches in inputTree, then disable for computation
        # the branches as requested in branchSelection
        inputTree.SetBranchStatus("*", 1)
        if branchSelection:
            branchSelection.selectBranches(inputTree)

        OutputTree.__init__(self, outputFile, outputTree, inputTree)
        self._inputTree = inputTree
        self._otherTrees = {}
        self._otherObjects = {}
        for k in inputFile.GetListOfKeys():
            kn = k.GetName()
            if kn == "Events":
                continue  # this we are doing
            elif kn in ("MetaData", "ParameterSets"):
                if provenance:
                    # treat content of other trees as if associated to event 0
                    self._otherTrees[kn] = inputFile.Get(
                        kn).CopyTree('1' if firstEntry == 0 else '0')
                    ROOT.SetOwnership(self._otherTrees[kn], False)
            elif kn in ("LuminosityBlocks", "Runs"):
                if not jsonFilter:
                    self._otherTrees[kn] = inputFile.Get(
                        kn).CopyTree('1' if firstEntry == 0 else '0')
                    ROOT.SetOwnership(self._otherTrees[kn], False)
                elif firstEntry == 0:
                    _isRun = (kn == "Runs")
                    _it = inputFile.Get(kn)
                    _ot = _it.CloneTree(0)
                    for ev in _it:
                        if (jsonFilter.filterRunOnly(ev.run) if _isRun else jsonFilter.filterRunLumi(ev.run, ev.luminosityBlock)):
                            _ot.Fill()
                    self._otherTrees[kn] = _ot
                    ROOT.SetOwnership(self._otherTrees[kn], False)
            elif k.GetClassName() == "TTree":
                print("Not copying unknown tree %s" % kn)
            else:
                self._otherObjects[kn] = inputFile.Get(kn)

    def fill(self):
        self._inputTree.readAllBranches()
        self._tree.Fill()

    def write(self):
        if self.outputbranchSelection:
            self.outputbranchSelection.selectBranches(self._tree)
        self._tree = self.tree().CopyTree('1', "",
                                          self.maxEntries if self.maxEntries else ROOT.TVirtualTreePlayer.kMaxEntries, 0)
        ROOT.SetOwnership(self._tree, False)
        OutputTree.write(self)
        for t in self._otherTrees.values():
            t.Write()
        for on, ov in self._otherObjects.items():
            self._file.WriteTObject(ov, on)

class FriendOutput(OutputTree):
    def __init__(self, inputFile, inputTree, outputFile, treeName="Friends"):
        outputFile.cd()
        outputTree = ROOT.TTree(
            treeName, "Friend tree for " + inputTree.GetName())
        ROOT.SetOwnership(outputTree, False)
        OutputTree.__init__(self, outputFile, outputTree, inputTree)

import json
import re
import ROOT
ROOT.PyConfig.IgnoreCommandLineOptions = True

class JSONFilter:
    def __init__(self, fname="", runsAndLumis={}):
        self.keep = {}
        if fname != "":
            jsonfp = open(fname, 'r')
            self.runsAndLumis = json.load(jsonfp)
            jsonfp.close()
        else:
            self.runsAndLumis = runsAndLumis
        for _run, lumis in self.runsAndLumis.items():
            run = int(_run)
            if run not in self.keep:
                self.keep[run] = []
            self.keep[run] += lumis
        for run in list(self.keep.keys()):
            if len(self.keep[run]) == 0:
                del self.keep[run]

    def filterRunLumi(self, run, lumi):
        try:
            for (l1, l2) in self.keep[run]:
                if l1 <= lumi and lumi <= l2:
                    return True
            return False
        except KeyError:
            return False

    def filterRunOnly(self, run):
        return (run in self.keep)

    def runCut(self):
        return "%d <= run && run <= %s" % (min(self.keep.keys()), max(self.keep.keys()))

    def filterEList(self, tree, elist):
        # FIXME this can be optimized for sure
        tree.SetBranchStatus("*", 0)
        tree.SetBranchStatus('run', 1)
        tree.SetBranchStatus('luminosityBlock', 1)
        filteredList = ROOT.TEntryList('filteredList', 'filteredList')
        if elist:
            for i in range(elist.GetN()):
                entry = elist.GetEntry(0) if i == 0 else elist.Next()
                tree.GetEntry(entry)
                if self.filterRunLumi(tree.run, tree.luminosityBlock):
                    filteredList.Enter(entry)
        else:
            for entry in range(tree.GetEntries()):
                tree.GetEntry(entry)
                if self.filterRunLumi(tree.run, tree.luminosityBlock):
                    filteredList.Enter(entry)
        tree.SetBranchStatus("*", 1)
        return filteredList

def preSkim(tree, jsonInput=None, cutstring=None, maxEntries=None, firstEntry=0):
    if jsonInput == None and cutstring == None:
        return None, None
    cut = None
    jsonFilter = None
    if jsonInput != None:
        if type(jsonInput) is dict:
            jsonFilter = JSONFilter(runsAndLumis=jsonInput)
        else:
            jsonFilter = JSONFilter(jsonInput)
        cut = jsonFilter.runCut()
    if cutstring != None:
        cut = "(%s) && (%s)" % (cutstring, cut) if cut else cutstring
    if maxEntries is None:
        maxEntries = ROOT.TVirtualTreePlayer.kMaxEntries
    while "AltBranch$" in cut:
        m = re.search(r"AltBranch\$\(\s*(\w+)\s*,\s*(\w+)\s*\)", cut)
        if not m:
            raise RuntimeError(
                "Error, found AltBranch$ in cut string, but it doesn't comply with the syntax this code can support. The cut is %r" % cut)
        cut = cut.replace(m.group(0), m.group(
            1) if tree.GetBranch(m.group(1)) else m.group(2))
    tree.Draw('>>elist', cut, "entrylist", maxEntries, firstEntry)
    elist = ROOT.gDirectory.Get('elist')
    if jsonInput:
        elist = jsonFilter.filterEList(tree, elist)
    return elist, jsonFilter

import types
import ROOT
ROOT.PyConfig.IgnoreCommandLineOptions = True

def InputTree(tree, entrylist=ROOT.MakeNullPointer(ROOT.TEntryList)):
    """add to the PyROOT wrapper of a TTree a TTreeReader and methods readBranch, arrayReader, valueReader"""
    if hasattr(tree, '_ttreereader'):
        return tree  # don't initialize twice
    tree.entry = -1
    tree._entrylist = entrylist
    tree._ttreereader = ROOT.TTreeReader(tree, tree._entrylist)
    ROOT.SetOwnership(tree._ttreereader, False)
    tree._ttreereader._isClean = True
    tree._ttrvs = {}
    tree._ttras = {}
    tree._leafTypes = {}
    tree._ttreereaderversion = 1
    tree.arrayReader = types.MethodType(getArrayReader, tree)
    tree.valueReader = types.MethodType(getValueReader, tree)
    tree.readBranch = types.MethodType(readBranch, tree)
    tree.gotoEntry = types.MethodType(_gotoEntry, tree)
    tree.readAllBranches = types.MethodType(_readAllBranches, tree)
    tree.entries = tree._ttreereader.GetEntries(False)
    tree._extrabranches = {}
    return tree

def getArrayReader(tree, branchName):
    """Make a reader for branch branchName containing a variable-length value array."""
    if branchName not in tree._ttras:
        if not tree.GetBranch(branchName):
            raise RuntimeError("Can't find branch '%s'" % branchName)
        if not tree.GetBranchStatus(branchName):
            raise RuntimeError("Branch %s has status=0" % branchName)
        leaf = tree.GetBranch(branchName).GetLeaf(branchName)
        if not bool(leaf.GetLeafCount()):
            raise RuntimeError("Branch %s is not a variable-length value array" % branchName)
        typ = leaf.GetTypeName()
        tree._ttras[branchName] = _makeArrayReader(tree, typ, branchName)
    return tree._ttras[branchName]

def getValueReader(tree, branchName):
    """Make a reader for branch branchName containing a single value."""
    if branchName not in tree._ttrvs:
        if not tree.GetBranch(branchName):
            raise RuntimeError("Can't find branch '%s'" % branchName)
        if not tree.GetBranchStatus(branchName):
            raise RuntimeError("Branch %s has status=0" % branchName)
        leaf = tree.GetBranch(branchName).GetLeaf(branchName)
        if bool(leaf.GetLeafCount()) or leaf.GetLen() != 1:
            raise RuntimeError("Branch %s is not a value" % branchName)
        typ = leaf.GetTypeName()
        tree._ttrvs[branchName] = _makeValueReader(tree, typ, branchName)
    return tree._ttrvs[branchName]

def clearExtraBranches(tree):
    tree._extrabranches = {}

def setExtraBranch(tree, name, val):
    tree._extrabranches[name] = val

def readBranch(tree, branchName):
    """Return the branch value if the branch is a value, and a TreeReaderArray if the branch is an array"""
    if tree._ttreereader._isClean:
        raise RuntimeError("readBranch must not be called before calling gotoEntry")
    if branchName in tree._extrabranches:
        return tree._extrabranches[branchName]
    elif branchName in tree._ttras:
        return tree._ttras[branchName]
    elif branchName in tree._ttrvs:
        ret = tree._ttrvs[branchName].Get()[0]
        return ord(ret) if type(ret) == str else ret
    else:
        branch = tree.GetBranch(branchName)
        if not branch:
            raise RuntimeError("Unknown branch %s" % branchName)
        if not tree.GetBranchStatus(branchName):
            raise RuntimeError("Branch %s has status=0" % branchName)
        leaf = branch.GetLeaf(branchName)
        typ = leaf.GetTypeName()
        if leaf.GetLen() == 1 and not bool(leaf.GetLeafCount()):
            _vr = _makeValueReader(tree, typ, branchName)
            # force calling SetEntry as a new ValueReader was created
            tree.gotoEntry(tree.entry, forceCall=True)
            ret = _vr.Get()[0]
            return ord(ret) if type(ret) == str else ret
        else:
            _ar = _makeArrayReader(tree, typ, branchName)
            # force calling SetEntry as a new ArrayReader was created
            tree.gotoEntry(tree.entry, forceCall=True)
            return _ar

####### PRIVATE IMPLEMENTATION PART #######

def _makeArrayReader(tree, typ, nam):
    if not tree._ttreereader._isClean:
        _remakeAllReaders(tree)
    ttra = ROOT.TTreeReaderArray(typ)(tree._ttreereader, nam)
    tree._leafTypes[nam] = typ
    tree._ttras[nam] = ttra
    return tree._ttras[nam]

def _makeValueReader(tree, typ, nam):
    if not tree._ttreereader._isClean:
        _remakeAllReaders(tree)
    ttrv = ROOT.TTreeReaderValue(typ)(tree._ttreereader, nam)
    tree._leafTypes[nam] = typ
    tree._ttrvs[nam] = ttrv
    return tree._ttrvs[nam]

def _remakeAllReaders(tree):
    _ttreereader = ROOT.TTreeReader(tree, getattr(tree, '_entrylist', ROOT.MakeNullPointer(ROOT.TEntryList)))
    ROOT.SetOwnership(_ttreereader, False)
    _ttreereader._isClean = True
    _ttrvs = {}
    for k in tree._ttrvs.keys():
        _ttrvs[k] = ROOT.TTreeReaderValue(tree._leafTypes[k])(_ttreereader, k)
    _ttras = {}
    for k in tree._ttras.keys():
        _ttras[k] = ROOT.TTreeReaderArray(tree._leafTypes[k])(_ttreereader, k)
    tree._ttrvs = _ttrvs
    tree._ttras = _ttras
    tree._ttreereader = _ttreereader
    tree._ttreereaderversion += 1

def _readAllBranches(tree):
    tree.GetEntry(_currentTreeEntry(tree))

def _currentTreeEntry(tree):
    if tree._entrylist:
        return tree._entrylist.GetEntry(tree.entry)
    else:
        return tree.entry

def _gotoEntry(tree, entry, forceCall=False):
    tree._ttreereader._isClean = False
    if tree.entry != entry or forceCall:
        if (tree.entry == entry - 1 and entry != 0):
            tree._ttreereader.Next()
        else:
            tree._ttreereader.SetEntry(entry)
        tree.entry = entry

#include "MhtjuProducerCppWorker.h"

std::pair<float, float> MhtjuProducerCppWorker::getHT() {
  TLorentzVector ht(0, 0, 0, 0);

  unsigned n = (*nJet).Get()[0];
  for (unsigned i = 0; i < n; i++) {
    TLorentzVector j_add(0, 0, 0, 0);
    j_add.SetPtEtaPhiM((*Jet_pt)[i], 0, (*Jet_phi)[i], 0);
    ht += j_add;
  }

  return std::pair<float, float>(ht.Pt(), ht.Phi());
};

